def get_unique_items(items):
    unique_items = []
    for item in items:
        if item not in unique_items:
            unique_items.append(item)
    return unique_items

def main():
    sample_list = [1, 2, 2, 3, 4, 4]
    print(get_unique_items(sample_list))

if __name__ == "__main__":
    main()

